create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null,display_name text,avatar_url text,email_verified boolean default false,github_connected boolean default false,xp int default 0,level int default 1,streak_days int default 0,leaderboard_public boolean default true,created_at timestamptz default now());
create table if not exists languages(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text);
create table if not exists topics(id uuid primary key default gen_random_uuid(),language_id uuid references languages(id) on delete cascade,slug text not null,title text not null,difficulty text,estimated_minutes int,content jsonb not null default '{}'::jsonb,sort_order int default 0,unique(language_id,slug));
create table if not exists code_examples(id uuid primary key default gen_random_uuid(),topic_id uuid references topics(id) on delete cascade,language text not null,compiler_version text,source_code text not null,expected_output text);
create table if not exists videos(id uuid primary key default gen_random_uuid(),title text not null,provider text,embed_url text,duration_seconds int,transcript text,sort_order int default 0);
create table if not exists libraries(id uuid primary key default gen_random_uuid(),language text not null,name text not null,version text,purpose text,import_syntax text,documentation_url text,example text);
create table if not exists quizzes(id uuid primary key default gen_random_uuid(),topic_id uuid references topics(id) on delete cascade,title text not null);
create table if not exists questions(id uuid primary key default gen_random_uuid(),quiz_id uuid references quizzes(id) on delete cascade,type text not null,prompt text not null,options jsonb,answer jsonb,explanation text);
create table if not exists quiz_attempts(id uuid primary key default gen_random_uuid(),quiz_id uuid references quizzes(id),user_id uuid references auth.users(id) on delete cascade,score int,correct int,wrong int,created_at timestamptz default now());
create table if not exists challenges(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,difficulty text,xp_reward int default 100,statement text,input_spec text,output_spec text,constraints text,test_cases jsonb,solution_code jsonb);
create table if not exists submissions(id uuid primary key default gen_random_uuid(),challenge_id uuid references challenges(id),user_id uuid references auth.users(id) on delete cascade,language text,source_code text,status text,execution_ms int,memory_kb int,created_at timestamptz default now());
create table if not exists projects(id uuid primary key default gen_random_uuid(),language text not null,title text not null,slug text unique not null,requirements text,concepts jsonb,starter_code jsonb,solution_code jsonb);
create table if not exists progress(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,topic_id uuid references topics(id) on delete cascade,completed boolean default false,percent int default 0,last_seen_at timestamptz default now(),unique(user_id,topic_id));
create table if not exists badges(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text,icon text);
create table if not exists user_badges(user_id uuid references auth.users(id) on delete cascade,badge_id uuid references badges(id) on delete cascade,earned_at timestamptz default now(),primary key(user_id,badge_id));
create table if not exists xp_transactions(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,amount int not null,reason text,created_at timestamptz default now());
create table if not exists streaks(user_id uuid primary key references auth.users(id) on delete cascade,current_days int default 0,longest_days int default 0,last_activity_date date);
create table if not exists compiler_jobs(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,language text not null,version text,source_code text not null,status text default 'queued',output text,error text,execution_ms int,memory_kb int,created_at timestamptz default now());
create index if not exists idx_topics_language on topics(language_id,sort_order); create index if not exists idx_progress_user on progress(user_id); create index if not exists idx_submissions_user on submissions(user_id,created_at desc); create index if not exists idx_compiler_jobs_user on compiler_jobs(user_id,created_at desc);
